mapper.select:
SELECT NOTICE_NUM as noticeNum, NOTICE_CONTENT as noticeContent, NOTICE_CATEGORY as noticeCategory, FARM_NUM as farmNum, REC_TIME as recTime FROM ( SELECT t1.*, ROW_NUMBER() OVER ( PARTITION BY t1.NOTICE_CATEGORY, DATE_FORMAT(t1.REC_TIME, '%Y-%m-%d %H:00:00') ORDER BY t1.REC_TIME ASC ) as rn FROM DANGER_NOTICE t1 WHERE t1.FARM_NUM = #{farmNum}
AND DATE(t1.REC_TIME) = CURDATE()
AND DATE(t1.REC_TIME) >= DATE_SUB(CURDATE(), INTERVAL 6 DAY) AND DATE(t1.REC_TIME) <= CURDATE()
AND DATE(t1.REC_TIME) >= DATE_SUB(CURDATE(), INTERVAL 29 DAY) AND DATE(t1.REC_TIME) <= CURDATE()
) ranked WHERE rn = 1 ORDER BY REC_TIME DESC LIMIT 500

mapper.delete:
